/* LearnForge — Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@400;500;600;700&display=swap');

:root {
  --brand-black: #000000;
  --brand-lime: #E6FF32;
  --brand-burgundy: #7F2A23;
  --brand-lime-hover: #d4ed2b;
  --brand-burgundy-light: #a33d34;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', sans-serif;
  color: #1a1a1a;
  background: #ffffff;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Plus Jakarta Sans', sans-serif;
}

/* Scrollbar */
::-webkit-scrollbar { width: 8px; }
::-webkit-scrollbar-track { background: #f1f1f1; }
::-webkit-scrollbar-thumb { background: #333; border-radius: 4px; }

/* Navigation */
.nav-fixed {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,0,0,0.06);
  transition: box-shadow 0.3s ease;
}

.nav-fixed.scrolled {
  box-shadow: 0 2px 20px rgba(0,0,0,0.08);
}

.nav-logo {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 800;
  font-size: 1.5rem;
  color: var(--brand-black);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 2px;
}

.nav-logo .logo-accent {
  color: var(--brand-black);
  background: var(--brand-lime);
  padding: 2px 6px;
  border-radius: 4px;
}

.nav-link {
  font-size: 0.875rem;
  font-weight: 500;
  color: #555;
  text-decoration: none;
  transition: color 0.2s ease;
  position: relative;
}

.nav-link:hover { color: var(--brand-black); }

.nav-link.active { color: var(--brand-black); font-weight: 600; }

.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--brand-lime);
  border-radius: 1px;
}

.nav-cta {
  background: var(--brand-black);
  color: var(--brand-lime);
  padding: 10px 24px;
  border-radius: 100px;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s ease;
  border: 2px solid var(--brand-black);
}

.nav-cta:hover {
  background: var(--brand-lime);
  color: var(--brand-black);
}

/* Mobile nav */
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--brand-black);
  margin: 5px 0;
  transition: all 0.3s ease;
  border-radius: 1px;
}

.mobile-menu-btn.open span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.mobile-menu-btn.open span:nth-child(2) { opacity: 0; }

.mobile-menu-btn.open span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

.mobile-nav {
  display: none;
  position: fixed;
  top: 65px;
  left: 0;
  right: 0;
  background: white;
  padding: 24px;
  border-bottom: 1px solid rgba(0,0,0,0.06);
  z-index: 49;
  box-shadow: 0 8px 30px rgba(0,0,0,0.1);
}

.mobile-nav.open { display: block; }

.mobile-nav a {
  display: block;
  padding: 12px 0;
  font-size: 1rem;
  font-weight: 500;
  color: #333;
  text-decoration: none;
  border-bottom: 1px solid #f0f0f0;
}

@media (max-width: 768px) {
  .mobile-menu-btn { display: block; }
  .desktop-nav { display: none !important; }
  .desktop-cta { display: none !important; }
}

/* Hero */
.hero-section {
  padding-top: 120px;
  padding-bottom: 60px;
  position: relative;
  overflow: hidden;
}

.hero-section::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.12) 0%, transparent 70%);
  pointer-events: none;
}

.hero-section::after {
  content: '';
  position: absolute;
  bottom: -150px;
  left: -150px;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(127,42,35,0.06) 0%, transparent 70%);
  pointer-events: none;
}

/* Stats Bar */
.stats-bar {
  background: var(--brand-black);
  color: white;
  padding: 48px 0;
}

.stat-item {
  text-align: center;
}

.stat-number {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 3rem;
  font-weight: 800;
  color: var(--brand-lime);
  line-height: 1.1;
}

.stat-label {
  font-size: 0.95rem;
  color: rgba(255,255,255,0.7);
  margin-top: 8px;
}

/* Cards */
.feature-card {
  background: white;
  border-radius: 16px;
  padding: 32px;
  border: 1px solid #f0f0f0;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.feature-card:hover {
  border-color: var(--brand-lime);
  box-shadow: 0 8px 30px rgba(230,255,50,0.1);
  transform: translateY(-2px);
}

.feature-card .card-icon {
  width: 48px;
  height: 48px;
  background: var(--brand-lime);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  font-size: 1.25rem;
}

.feature-card .card-icon.burgundy {
  background: var(--brand-burgundy);
  color: white;
}

/* Tab Switch */
.tab-switch {
  display: inline-flex;
  background: #f5f5f5;
  border-radius: 100px;
  padding: 4px;
  gap: 4px;
}

.tab-switch-btn {
  padding: 10px 24px;
  border-radius: 100px;
  font-size: 0.875rem;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: all 0.3s ease;
  background: transparent;
  color: #666;
}

.tab-switch-btn.active {
  background: var(--brand-black);
  color: var(--brand-lime);
}

/* Tab Content Panels */
.tab-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}

.tab-panel.active { display: block; }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Testimonial Carousel */
.carousel-container {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-slide {
  flex: 0 0 100%;
  padding: 0 12px;
}

@media (min-width: 768px) {
  .carousel-slide { flex: 0 0 50%; }
}

@media (min-width: 1024px) {
  .carousel-slide { flex: 0 0 33.333%; }
}

.testimonial-card {
  background: white;
  border: 1px solid #f0f0f0;
  border-radius: 16px;
  padding: 32px;
  height: 100%;
  transition: all 0.3s ease;
}

.testimonial-card:hover {
  box-shadow: 0 8px 30px rgba(0,0,0,0.08);
}

.testimonial-card .quote-badge {
  display: inline-block;
  background: var(--brand-lime);
  color: var(--brand-black);
  padding: 4px 12px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 16px;
}

.testimonial-card .quote-text {
  font-size: 1rem;
  line-height: 1.7;
  color: #333;
  margin-bottom: 20px;
  font-style: italic;
}

.testimonial-card .quote-author {
  font-weight: 600;
  color: var(--brand-black);
  font-size: 0.9rem;
}

.testimonial-card .quote-org {
  color: #888;
  font-size: 0.8rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid #e0e0e0;
  background: white;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
  font-size: 1.1rem;
  color: #333;
}

.carousel-btn:hover {
  border-color: var(--brand-black);
  background: var(--brand-black);
  color: var(--brand-lime);
}

.carousel-dots {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-top: 24px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #ddd;
  border: none;
  cursor: pointer;
  transition: all 0.3s ease;
  padding: 0;
}

.carousel-dot.active {
  background: var(--brand-black);
  width: 24px;
  border-radius: 4px;
}

/* FAQ Accordion */
.faq-item {
  border: 1px solid #f0f0f0;
  border-radius: 12px;
  margin-bottom: 12px;
  overflow: hidden;
  transition: all 0.3s ease;
}

.faq-item:hover {
  border-color: #ddd;
}

.faq-item.active {
  border-color: var(--brand-lime);
  box-shadow: 0 4px 15px rgba(230,255,50,0.1);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  cursor: pointer;
  background: white;
  border: none;
  width: 100%;
  text-align: left;
  font-size: 1rem;
  font-weight: 600;
  color: var(--brand-black);
  font-family: 'Plus Jakarta Sans', sans-serif;
  transition: background 0.2s ease;
}

.faq-question:hover { background: #fafafa; }

.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #f5f5f5;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s ease;
  flex-shrink: 0;
  margin-left: 16px;
  font-size: 0.8rem;
}

.faq-item.active .faq-icon {
  background: var(--brand-lime);
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.3s ease;
}

.faq-answer-inner {
  padding: 0 24px 20px;
  color: #555;
  line-height: 1.7;
  font-size: 0.95rem;
}

/* Integrations Grid */
.integration-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: white;
  border: 1px solid #f0f0f0;
  border-radius: 12px;
  font-weight: 600;
  font-size: 0.85rem;
  color: #555;
  transition: all 0.3s ease;
  height: 72px;
}

.integration-logo:hover {
  border-color: var(--brand-lime);
  box-shadow: 0 4px 15px rgba(230,255,50,0.08);
  transform: translateY(-2px);
}

/* CTA Banner */
.cta-banner {
  background: var(--brand-black);
  color: white;
  border-radius: 24px;
  padding: 64px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -100px;
  right: -100px;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(230,255,50,0.15) 0%, transparent 70%);
  pointer-events: none;
}

.cta-banner::after {
  content: '';
  position: absolute;
  bottom: -80px;
  left: -80px;
  width: 250px;
  height: 250px;
  background: radial-gradient(circle, rgba(127,42,35,0.1) 0%, transparent 70%);
  pointer-events: none;
}

.cta-btn-primary {
  display: inline-block;
  background: var(--brand-lime);
  color: var(--brand-black);
  padding: 14px 36px;
  border-radius: 100px;
  font-weight: 700;
  font-size: 1rem;
  text-decoration: none;
  transition: all 0.2s ease;
  border: 2px solid var(--brand-lime);
}

.cta-btn-primary:hover {
  background: var(--brand-lime-hover);
  transform: translateY(-1px);
  box-shadow: 0 8px 25px rgba(230,255,50,0.3);
}

.cta-btn-secondary {
  display: inline-block;
  background: transparent;
  color: white;
  padding: 14px 36px;
  border-radius: 100px;
  font-weight: 600;
  font-size: 1rem;
  text-decoration: none;
  transition: all 0.2s ease;
  border: 2px solid rgba(255,255,255,0.3);
}

.cta-btn-secondary:hover {
  border-color: white;
  background: rgba(255,255,255,0.05);
}

/* Section Styles */
.section-label {
  display: inline-block;
  background: var(--brand-lime);
  color: var(--brand-black);
  padding: 6px 16px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 16px;
}

.section-title {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  line-height: 1.15;
  color: var(--brand-black);
  margin-bottom: 16px;
}

.section-subtitle {
  font-size: 1.1rem;
  color: #666;
  line-height: 1.7;
  max-width: 640px;
}

/* Pricing Cards */
.pricing-card {
  background: white;
  border: 2px solid #f0f0f0;
  border-radius: 20px;
  padding: 36px;
  transition: all 0.3s ease;
  position: relative;
}

.pricing-card:hover {
  box-shadow: 0 12px 40px rgba(0,0,0,0.1);
}

.pricing-card.featured {
  border-color: var(--brand-lime);
  box-shadow: 0 12px 40px rgba(230,255,50,0.15);
}

.pricing-card.featured .pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--brand-lime);
  color: var(--brand-black);
  padding: 4px 16px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 700;
}

.pricing-price {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--brand-black);
}

.pricing-period {
  font-size: 0.9rem;
  color: #888;
  font-weight: 400;
}

.pricing-feature {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 0;
  font-size: 0.9rem;
  color: #444;
}

.pricing-feature .check {
  color: #22c55e;
  font-weight: 700;
  font-size: 1rem;
}

/* Hero Preview Panels */
.hero-preview {
  background: #f8f8f8;
  border-radius: 16px;
  border: 1px solid #eee;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0,0,0,0.08);
}

.hero-preview-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
  background: #f0f0f0;
  border-bottom: 1px solid #e5e5e5;
}

.hero-preview-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #ddd;
}

.hero-preview-dot.red { background: #ff5f57; }
.hero-preview-dot.yellow { background: #febc2e; }
.hero-preview-dot.green { background: #28c840; }

.hero-preview-body {
  padding: 32px;
  min-height: 280px;
}

/* Steps */
.step-number {
  width: 48px;
  height: 48px;
  background: var(--brand-lime);
  color: var(--brand-black);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 800;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.step-connector {
  width: 2px;
  height: 40px;
  background: linear-gradient(to bottom, var(--brand-lime), transparent);
  margin: 8px 0 8px 23px;
}

/* Tools Grid */
.tool-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #f8f8f8;
  border: 1px solid #eee;
  padding: 10px 18px;
  border-radius: 100px;
  font-size: 0.85rem;
  font-weight: 500;
  color: #444;
  transition: all 0.2s ease;
}

.tool-tag:hover {
  background: var(--brand-lime);
  border-color: var(--brand-lime);
  color: var(--brand-black);
}

/* Product type cards */
.product-card {
  background: white;
  border: 1px solid #f0f0f0;
  border-radius: 20px;
  padding: 36px;
  transition: all 0.4s ease;
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--brand-lime);
  transform: scaleX(0);
  transition: transform 0.3s ease;
  transform-origin: left;
}

.product-card:hover::before { transform: scaleX(1); }

.product-card:hover {
  box-shadow: 0 12px 40px rgba(0,0,0,0.08);
  transform: translateY(-4px);
}

/* Resource Cards */
.resource-card {
  background: white;
  border: 1px solid #f0f0f0;
  border-radius: 16px;
  padding: 28px;
  transition: all 0.3s ease;
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.resource-card:hover {
  box-shadow: 0 8px 25px rgba(0,0,0,0.08);
  border-color: var(--brand-lime);
}

/* Spotlight Cards */
.spotlight-card {
  background: white;
  border: 1px solid #f0f0f0;
  border-radius: 20px;
  overflow: hidden;
  transition: all 0.3s ease;
}

.spotlight-card:hover {
  box-shadow: 0 12px 40px rgba(0,0,0,0.08);
  transform: translateY(-4px);
}

.spotlight-card-img {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
}

/* Animations */
@keyframes slideUp {
  from { opacity: 0; transform: translateY(30px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideInLeft {
  from { opacity: 0; transform: translateX(-30px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

.animate-on-scroll {
  opacity: 0;
  transform: translateY(30px);
  transition: all 0.7s cubic-bezier(0.4, 0, 0.2, 1);
}

.animate-on-scroll.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Footer */
.footer-section {
  background: var(--brand-black);
  color: white;
  padding: 64px 0 32px;
}

.footer-col h4 {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 700;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--brand-lime);
  margin-bottom: 16px;
}

.footer-col a {
  display: block;
  color: rgba(255,255,255,0.6);
  text-decoration: none;
  font-size: 0.9rem;
  padding: 4px 0;
  transition: color 0.2s ease;
}

.footer-col a:hover { color: white; }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  margin-top: 48px;
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  color: rgba(255,255,255,0.4);
  font-size: 0.85rem;
}

/* File type badges */
.file-badge {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 24px 16px;
  background: #fafafa;
  border: 1px solid #eee;
  border-radius: 16px;
  transition: all 0.3s ease;
  text-align: center;
}

.file-badge:hover {
  border-color: var(--brand-lime);
  background: white;
  box-shadow: 0 4px 15px rgba(230,255,50,0.1);
}

.file-badge .file-icon {
  width: 48px;
  height: 48px;
  background: var(--brand-lime);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
}

.file-badge .file-name {
  font-size: 0.85rem;
  font-weight: 600;
  color: #333;
}

/* Why Choose Tab Content */
.feature-list-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 8px 0;
}

.feature-list-item .check-icon {
  width: 22px;
  height: 22px;
  background: var(--brand-lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--brand-black);
  flex-shrink: 0;
  margin-top: 2px;
}

.feature-list-item span {
  font-size: 0.95rem;
  color: #444;
  line-height: 1.5;
}

/* Responsive */
@media (max-width: 768px) {
  .hero-section { padding-top: 100px; padding-bottom: 40px; }
  .stat-number { font-size: 2rem; }
  .cta-banner { padding: 40px 24px; border-radius: 16px; }
  .pricing-card { padding: 24px; }
  .section-title { font-size: 1.75rem; }
}

/* Product Demo Accordion */
.demo-accordion {
  border: 1px solid #f0f0f0;
  border-radius: 16px;
  overflow: hidden;
}

.demo-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
