  transition: all 0.3s ease;
  text-align: center;
}

.file-badge:hover {
  border-color: var(--brand-lime);
  background: white;
  box-shadow: 0 4px 15px rgba(230,255,50,0.1);
}

.file-badge .file-icon {
  width: 48px;
  height: 48px;
  background: var(--brand-lime);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
}

.file-badge .file-name {
  font-size: 0.85rem;
  font-weight: 600;
  color: #333;
}

/* Why Choose Tab Content */
.feature-list-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
