}

.feature-list-item .check-icon {
  width: 22px;
  height: 22px;
  background: var(--brand-lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--brand-black);
  flex-shrink: 0;
  margin-top: 2px;
}

.feature-list-item span {
  font-size: 0.95rem;
  color: #444;
  line-height: 1.5;
}

/* Responsive */
