  .hero-section { padding-top: 100px; padding-bottom: 40px; }
  .stat-number { font-size: 2rem; }
  .cta-banner { padding: 40px 24px; border-radius: 16px; }
  .pricing-card { padding: 24px; }
  .section-title { font-size: 1.75rem; }
}

/* Product Demo Accordion */
.demo-accordion {
  border: 1px solid #f0f0f0;
  border-radius: 16px;
  overflow: hidden;
}

.demo-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  cursor: pointer;
  background: white;
  border: none;
  width: 100%;
  text-align: left;
  font-weight: 600;
  font-size: 1rem;
  color: var(--brand-black);
  font-family: 'Plus Jakarta Sans', sans-serif;
}

.demo-accordion-header .toggle-icon {
  transition: transform 0.3s ease;
}

.demo-accordion.active .toggle-icon {
  transform: rotate(180deg);
}

.demo-accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.demo-accordion-body-inner {
  padding: 0 24px 24px;
}

/* Global Scale Section */
.globe-visual {
  width: 200px;
  height: 200px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--brand-lime) 0%, #a8d600 50%, var(--brand-burgundy) 100%);
